// Turn graph rows into simple facts: 'Louis Johnson -PLAYED_ON [bass]-> Thriller (1982)'
const d = $input.first().json.data;
const facts = d.values.map(([from, relation, to]) => `${from} -${relation}-> ${to}`);
return [{ json: { result: facts.length ? facts.join('\n') : `No graph data found for "${$('When Executed by Another Workflow').first().json.name}".` } }];
